17	package com.google.zxing.qrcode.encoder;
18	
19	/**
20	 * @author Satoru Takabayashi
21	 * @author Daniel Switkin
22	 * @author Sean Owen
23	 */
24	final class MaskUtil {
25	
26	  // Penalty weights from section 6.8.2.1
27	  private static final int N1 = 3;
28	  private static final int N2 = 3;
29	  private static final int N3 = 40;
30	  private static final int N4 = 10;
31	
32	  private MaskUtil() {
33	    // do nothing
34	  }
35	
36	  /**
37	   * Apply mask penalty rule 1 and return the penalty. Find repetitive cells with the same color and
38	   * give penalty to them. Example: 00000 or 11111.
39	   */
40	  static int applyMaskPenaltyRule1(ByteMatrix matrix) {
41	    return applyMaskPenaltyRule1Internal(matrix, true) + applyMaskPenaltyRule1Internal(matrix, false);
42	  }
43	
44	  /**
45	   * Apply mask penalty rule 2 and return the penalty. Find 2x2 blocks with the same color and give
46	   * penalty to them. This is actually equivalent to the spec's rule, which is to find MxN blocks and give a
47	   * penalty proportional to (M-1)x(N-1), because this is the number of 2x2 blocks inside such a block.
48	   */
49	  static int applyMaskPenaltyRule2(ByteMatrix matrix) {
50	    int penalty = 0;
51	    byte[][] array = matrix.getArray();
52	    int width = matrix.getWidth();
53	    int height = matrix.getHeight();
54	    for (int y = 0; y < height - 1; y++) {
55	      byte[] arrayY = array[y];
56	      for (int x = 0; x < width - 1; x++) {
57	        int value = arrayY[x];
58	        if (value == arrayY[x + 1] && value == array[y + 1][x] && value == array[y + 1][x + 1]) {
59	          penalty++;
60	        }
61	      }
62	    }
63	    return N2 * penalty;
64	  }
65	
66	  /**
67	   * Apply mask penalty rule 3 and return the penalty. Find consecutive runs of 1:1:3:1:1:4
68	   * starting with black, or 4:1:1:3:1:1 starting with white, and give penalty to them.  If we
69	   * find patterns like 000010111010000, we give penalty once.
70	   */
71	  static int applyMaskPenaltyRule3(ByteMatrix matrix) {
72	    int numPenalties = 0;
73	    byte[][] array = matrix.getArray();
74	    int width = matrix.getWidth();
75	    int height = matrix.getHeight();
76	    for (int y = 0; y < height; y++) {
77	      for (int x = 0; x < width; x++) {
78	        byte[] arrayY = array[y];  // We can at least optimize this access
79	        if (x + 6 < width &&
80	            arrayY[x] == 1 &&
81	            arrayY[x + 1] == 0 &&
82	            arrayY[x + 2] == 1 &&
83	            arrayY[x + 3] == 1 &&
84	            arrayY[x + 4] == 1 &&
85	            arrayY[x + 5] == 0 &&
86	            arrayY[x + 6] == 1 &&
87	            (isWhiteHorizontal(arrayY, x - 4, x) || isWhiteHorizontal(arrayY, x + 7, x + 11))) {
88	          numPenalties++;
89	        }
90	        if (y + 6 < height &&
91	            array[y][x] == 1 &&
92	            array[y + 1][x] == 0 &&
93	            array[y + 2][x] == 1 &&
94	            array[y + 3][x] == 1 &&
95	            array[y + 4][x] == 1 &&
96	            array[y + 5][x] == 0 &&
97	            array[y + 6][x] == 1 &&
98	            (isWhiteVertical(array, x, y - 4, y) || isWhiteVertical(array, x, y + 7, y + 11))) {
99	          numPenalties++;
100	        }
101	      }
102	    }
103	    return numPenalties * N3;
104	  }
105	
106	  private static boolean isWhiteHorizontal(byte[] rowArray, int from, int to) {
107	    if (from < 0 || rowArray.length < to) {
108	      return false;
109	    }
110	    for (int i = from; i < to; i++) {
111	      if (rowArray[i] == 1) {
112	        return false;
113	      }
114	    }
115	    return true;
116	  }
117	
118	  private static boolean isWhiteVertical(byte[][] array, int col, int from, int to) {
119	    if (from < 0 || array.length < to) {
120	      return false;
121	    }
122	    for (int i = from; i < to; i++) {
123	      if (array[i][col] == 1) {
124	        return false;
125	      }
126	    }
127	    return true;
128	  }
129	
130	  /**
131	   * Apply mask penalty rule 4 and return the penalty. Calculate the ratio of dark cells and give
132	   * penalty if the ratio is far from 50%. It gives 10 penalty for 5% distance.
133	   */
134	  static int applyMaskPenaltyRule4(ByteMatrix matrix) {
135	    int numDarkCells = 0;
136	    byte[][] array = matrix.getArray();
137	    int width = matrix.getWidth();
138	    int height = matrix.getHeight();
139	    for (int y = 0; y < height; y++) {
140	      byte[] arrayY = array[y];
141	      for (int x = 0; x < width; x++) {
142	        if (arrayY[x] == 1) {
143	          numDarkCells++;
144	        }
145	      }
146	    }
147	    int numTotalCells = matrix.getHeight() * matrix.getWidth();
148	    int fivePercentVariances = Math.abs(numDarkCells * 2 - numTotalCells) * 10 / numTotalCells;
149	    return fivePercentVariances * N4;
150	  }
151	
152	  /**
153	   * Return the mask bit for "getMaskPattern" at "x" and "y". See 8.8 of JISX0510:2004 for mask
154	   * pattern conditions.
155	   */
156	  static boolean getDataMaskBit(int maskPattern, int x, int y) {
157	    int intermediate;
158	    int temp;
159	    switch (maskPattern) {
160	      case 0:
161	        intermediate = (y + x) & 0x1;
162	        break;
163	      case 1:
164	        intermediate = y & 0x1;
165	        break;
166	      case 2:
167	        intermediate = x % 3;
168	        break;
169	      case 3:
170	        intermediate = (y + x) % 3;
171	        break;
172	      case 4:
173	        intermediate = ((y / 2) + (x / 3)) & 0x1;
174	        break;
175	      case 5:
176	        temp = y * x;
177	        intermediate = (temp & 0x1) + (temp % 3);
178	        break;
179	      case 6:
180	        temp = y * x;
181	        intermediate = ((temp & 0x1) + (temp % 3)) & 0x1;
182	        break;
183	      case 7:
184	        temp = y * x;
185	        intermediate = ((temp % 3) + ((y + x) & 0x1)) & 0x1;
186	        break;
187	      default:
188	        throw new IllegalArgumentException("Invalid mask pattern: " + maskPattern);
189	    }
190	    return intermediate == 0;
191	  }
192	
193	  /**
194	   * Helper function for applyMaskPenaltyRule1. We need this for doing this calculation in both
195	   * vertical and horizontal orders respectively.
196	   */
197	  private static int applyMaskPenaltyRule1Internal(ByteMatrix matrix, boolean isHorizontal) {
198	    int penalty = 0;
199	    int iLimit = isHorizontal ? matrix.getHeight() : matrix.getWidth();
200	    int jLimit = isHorizontal ? matrix.getWidth() : matrix.getHeight();
201	    byte[][] array = matrix.getArray();
202	    for (int i = 0; i < iLimit; i++) {
203	      int numSameBitCells = 0;
204	      int prevBit = -1;
205	      for (int j = 0; j < jLimit; j++) {
206	        int bit = isHorizontal ? array[i][j] : array[j][i];
207	        if (bit == prevBit) {
208	          numSameBitCells++;
209	        } else {
210	          if (numSameBitCells >= 5) {
211	            penalty += N1 + (numSameBitCells - 5);
212	          }
213	          numSameBitCells = 1;  // Include the cell itself.
214	          prevBit = bit;
215	        }
216	      }
217	      if (numSameBitCells >= 5) {
218	        penalty += N1 + (numSameBitCells - 5);
219	      }
220	    }
221	    return penalty;
222	  }
223	
224	}
