17	package com.google.zxing.pdf417.decoder.ec;
18	
19	/**
20	 * @author Sean Owen
21	 */
22	final class ModulusPoly {
23	
24	  private final ModulusGF field;
25	  private final int[] coefficients;
26	
27	  ModulusPoly(ModulusGF field, int[] coefficients) {
28	    if (coefficients.length == 0) {
29	      throw new IllegalArgumentException();
30	    }
31	    this.field = field;
32	    int coefficientsLength = coefficients.length;
33	    if (coefficientsLength > 1 && coefficients[0] == 0) {
34	      // Leading term must be non-zero for anything except the constant polynomial "0"
35	      int firstNonZero = 1;
36	      while (firstNonZero < coefficientsLength && coefficients[firstNonZero] == 0) {
37	        firstNonZero++;
38	      }
39	      if (firstNonZero == coefficientsLength) {
40	        this.coefficients = new int[]{0};
41	      } else {
42	        this.coefficients = new int[coefficientsLength - firstNonZero];
43	        System.arraycopy(coefficients,
44	            firstNonZero,
45	            this.coefficients,
46	            0,
47	            this.coefficients.length);
48	      }
49	    } else {
50	      this.coefficients = coefficients;
51	    }
52	  }
53	
54	  int[] getCoefficients() {
55	    return coefficients;
56	  }
57	
58	  /**
59	   * @return degree of this polynomial
60	   */
61	  int getDegree() {
62	    return coefficients.length - 1;
63	  }
64	
65	  /**
66	   * @return true iff this polynomial is the monomial "0"
67	   */
68	  boolean isZero() {
69	    return coefficients[0] == 0;
70	  }
71	
72	  /**
73	   * @return coefficient of x^degree term in this polynomial
74	   */
75	  int getCoefficient(int degree) {
76	    return coefficients[coefficients.length - 1 - degree];
77	  }
78	
79	  /**
80	   * @return evaluation of this polynomial at a given point
81	   */
82	  int evaluateAt(int a) {
83	    if (a == 0) {
84	      // Just return the x^0 coefficient
85	      return getCoefficient(0);
86	    }
87	    if (a == 1) {
88	      // Just the sum of the coefficients
89	      int result = 0;
90	      for (int coefficient : coefficients) {
91	        result = field.add(result, coefficient);
92	      }
93	      return result;
94	    }
95	    int result = coefficients[0];
96	    int size = coefficients.length;
97	    for (int i = 1; i < size; i++) {
98	      result = field.add(field.multiply(a, result), coefficients[i]);
99	    }
100	    return result;
101	  }
102	
103	  ModulusPoly add(ModulusPoly other) {
104	    if (!field.equals(other.field)) {
105	      throw new IllegalArgumentException("ModulusPolys do not have same ModulusGF field");
106	    }
107	    if (isZero()) {
108	      return other;
109	    }
110	    if (other.isZero()) {
111	      return this;
112	    }
113	
114	    int[] smallerCoefficients = this.coefficients;
115	    int[] largerCoefficients = other.coefficients;
116	    if (smallerCoefficients.length > largerCoefficients.length) {
117	      int[] temp = smallerCoefficients;
118	      smallerCoefficients = largerCoefficients;
119	      largerCoefficients = temp;
120	    }
121	    int[] sumDiff = new int[largerCoefficients.length];
122	    int lengthDiff = largerCoefficients.length - smallerCoefficients.length;
123	    // Copy high-order terms only found in higher-degree polynomial's coefficients
124	    System.arraycopy(largerCoefficients, 0, sumDiff, 0, lengthDiff);
125	
126	    for (int i = lengthDiff; i < largerCoefficients.length; i++) {
127	      sumDiff[i] = field.add(smallerCoefficients[i - lengthDiff], largerCoefficients[i]);
128	    }
129	
130	    return new ModulusPoly(field, sumDiff);
131	  }
132	
133	  ModulusPoly subtract(ModulusPoly other) {
134	    if (!field.equals(other.field)) {
135	      throw new IllegalArgumentException("ModulusPolys do not have same ModulusGF field");
136	    }
137	    if (other.isZero()) {
138	      return this;
139	    }
140	    return add(other.negative());
141	  }
142	
143	  ModulusPoly multiply(ModulusPoly other) {
144	    if (!field.equals(other.field)) {
145	      throw new IllegalArgumentException("ModulusPolys do not have same ModulusGF field");
146	    }
147	    if (isZero() || other.isZero()) {
148	      return field.getZero();
149	    }
150	    int[] aCoefficients = this.coefficients;
151	    int aLength = aCoefficients.length;
152	    int[] bCoefficients = other.coefficients;
153	    int bLength = bCoefficients.length;
154	    int[] product = new int[aLength + bLength - 1];
155	    for (int i = 0; i < aLength; i++) {
156	      int aCoeff = aCoefficients[i];
157	      for (int j = 0; j < bLength; j++) {
158	        product[i + j] = field.add(product[i + j], field.multiply(aCoeff, bCoefficients[j]));
159	      }
160	    }
161	    return new ModulusPoly(field, product);
162	  }
163	
164	  ModulusPoly negative() {
165	    int size = coefficients.length;
166	    int[] negativeCoefficients = new int[size];
167	    for (int i = 0; i < size; i++) {
168	      negativeCoefficients[i] = field.subtract(0, coefficients[i]);
169	    }
170	    return new ModulusPoly(field, negativeCoefficients);
171	  }
172	
173	  ModulusPoly multiply(int scalar) {
174	    if (scalar == 0) {
175	      return field.getZero();
176	    }
177	    if (scalar == 1) {
178	      return this;
179	    }
180	    int size = coefficients.length;
181	    int[] product = new int[size];
182	    for (int i = 0; i < size; i++) {
183	      product[i] = field.multiply(coefficients[i], scalar);
184	    }
185	    return new ModulusPoly(field, product);
186	  }
187	
188	  ModulusPoly multiplyByMonomial(int degree, int coefficient) {
189	    if (degree < 0) {
190	      throw new IllegalArgumentException();
191	    }
192	    if (coefficient == 0) {
193	      return field.getZero();
194	    }
195	    int size = coefficients.length;
196	    int[] product = new int[size + degree];
197	    for (int i = 0; i < size; i++) {
198	      product[i] = field.multiply(coefficients[i], coefficient);
199	    }
200	    return new ModulusPoly(field, product);
201	  }
202	
203	  @Override
204	  public String toString() {
205	    StringBuilder result = new StringBuilder(8 * getDegree());
206	    for (int degree = getDegree(); degree >= 0; degree--) {
207	      int coefficient = getCoefficient(degree);
208	      if (coefficient != 0) {
209	        if (coefficient < 0) {
210	          result.append(" - ");
211	          coefficient = -coefficient;
212	        } else {
213	          if (result.length() > 0) {
214	            result.append(" + ");
215	          }
216	        }
217	        if (degree == 0 || coefficient != 1) {
218	          result.append(coefficient);
219	        }
220	        if (degree != 0) {
221	          if (degree == 1) {
222	            result.append('x');
223	          } else {
224	            result.append("x^");
225	            result.append(degree);
226	          }
227	        }
228	      }
229	    }
230	    return result.toString();
231	  }
232	
233	}
