167	  BarcodeMetadata getBarcodeMetadata() {
168	    Codeword[] codewords = getCodewords();
169	    BarcodeValue barcodeColumnCount = new BarcodeValue();
170	    BarcodeValue barcodeRowCountUpperPart = new BarcodeValue();
171	    BarcodeValue barcodeRowCountLowerPart = new BarcodeValue();
172	    BarcodeValue barcodeECLevel = new BarcodeValue();
173	    for (Codeword codeword : codewords) {
174	      if (codeword == null) {
175	        continue;
176	      }
177	      codeword.setRowNumberAsRowIndicatorColumn();
178	      int rowIndicatorValue = codeword.getValue() % 30;
179	      int codewordRowNumber = codeword.getRowNumber();
180	      if (!isLeft) {
181	        codewordRowNumber += 2;
182	      }
183	      switch (codewordRowNumber % 3) {
184	        case 0:
185	          barcodeRowCountUpperPart.setValue(rowIndicatorValue * 3 + 1);
186	          break;
187	        case 1:
188	          barcodeECLevel.setValue(rowIndicatorValue / 3);
189	          barcodeRowCountLowerPart.setValue(rowIndicatorValue % 3);
190	          break;
191	        case 2:
192	          barcodeColumnCount.setValue(rowIndicatorValue + 1);
193	          break;
194	      }
195	    }
196	    // Maybe we should check if we have ambiguous values?
197	    if ((barcodeColumnCount.getValue().length == 0) ||
198	        (barcodeRowCountUpperPart.getValue().length == 0) ||
199	        (barcodeRowCountLowerPart.getValue().length == 0) ||
200	        (barcodeECLevel.getValue().length == 0) ||
201	        barcodeColumnCount.getValue()[0] < 1 ||
202	        barcodeRowCountUpperPart.getValue()[0] + barcodeRowCountLowerPart.getValue()[0] <
203	            PDF417Common.MIN_ROWS_IN_BARCODE ||
204	        barcodeRowCountUpperPart.getValue()[0] + barcodeRowCountLowerPart.getValue()[0] >
205	            PDF417Common.MAX_ROWS_IN_BARCODE) {
206	      return null;
207	    }
208	    BarcodeMetadata barcodeMetadata = new BarcodeMetadata(barcodeColumnCount.getValue()[0],
209	        barcodeRowCountUpperPart.getValue()[0], barcodeRowCountLowerPart.getValue()[0], barcodeECLevel.getValue()[0]);
210	    removeIncorrectCodewords(codewords, barcodeMetadata);
211	    return barcodeMetadata;
212	  }
213	
214	  private void removeIncorrectCodewords(Codeword[] codewords, BarcodeMetadata barcodeMetadata) {
215	    // Remove codewords which do not match the metadata
216	    // TODO Maybe we should keep the incorrect codewords for the start and end positions?
217	    for (int codewordRow = 0; codewordRow < codewords.length; codewordRow++) {
218	      Codeword codeword = codewords[codewordRow];
219	      if (codewords[codewordRow] == null) {
220	        continue;
221	      }
222	      int rowIndicatorValue = codeword.getValue() % 30;
223	      int codewordRowNumber = codeword.getRowNumber();
224	      if (codewordRowNumber > barcodeMetadata.getRowCount()) {
225	        codewords[codewordRow] = null;
226	        continue;
227	      }
228	      if (!isLeft) {
229	        codewordRowNumber += 2;
230	      }
231	      switch (codewordRowNumber % 3) {
232	        case 0:
233	          if (rowIndicatorValue * 3 + 1 != barcodeMetadata.getRowCountUpperPart()) {
234	            codewords[codewordRow] = null;
235	          }
236	          break;
237	        case 1:
238	          if (rowIndicatorValue / 3 != barcodeMetadata.getErrorCorrectionLevel() ||
239	              rowIndicatorValue % 3 != barcodeMetadata.getRowCountLowerPart()) {
240	            codewords[codewordRow] = null;
241	          }
242	          break;
243	        case 2:
244	          if (rowIndicatorValue + 1 != barcodeMetadata.getColumnCount()) {
245	            codewords[codewordRow] = null;
246	          }
247	          break;
248	      }
249	    }
250	  }
