218	  /**
219	   * Corrects the parameter bits using Reed-Solomon algorithm.
220	   *
221	   * @param parameterData parameter bits
222	   * @param compact true if this is a compact Aztec code
223	   * @return the corrected parameter
224	   * @throws NotFoundException if the array contains too many errors
225	   */
226	  private static CorrectedParameter getCorrectedParameterData(long parameterData,
227	                                                              boolean compact) throws NotFoundException {
228	    int numCodewords;
229	    int numDataCodewords;
230	
231	    if (compact) {
232	      numCodewords = 7;
233	      numDataCodewords = 2;
234	    } else {
235	      numCodewords = 10;
236	      numDataCodewords = 4;
237	    }
238	
239	    int numECCodewords = numCodewords - numDataCodewords;
240	    int[] parameterWords = new int[numCodewords];
241	    for (int i = numCodewords - 1; i >= 0; --i) {
242	      parameterWords[i] = (int) parameterData & 0xF;
243	      parameterData >>= 4;
244	    }
245	
246	    int errorsCorrected = 0;
247	    try {
248	      ReedSolomonDecoder rsDecoder = new ReedSolomonDecoder(GenericGF.AZTEC_PARAM);
249	      errorsCorrected = rsDecoder.decodeWithECCount(parameterWords, numECCodewords);
250	    } catch (ReedSolomonException ignored) {
251	      throw NotFoundException.getNotFoundInstance();
252	    }
253	
254	    // Toss the error correction.  Just return the data as an integer
255	    int result = 0;
256	    for (int i = 0; i < numDataCodewords; i++) {
257	      result = (result << 4) + parameterWords[i];
258	    }
259	    return new CorrectedParameter(result, errorsCorrected);
260	  }
261	
262	  /**
263	   * Finds the corners of a bull-eye centered on the passed point.
264	   * This returns the centers of the diagonal points just outside the bull's eye
265	   * Returns [topRight, bottomRight, bottomLeft, topLeft]
266	   *
267	   * @param pCenter Center point
268	   * @return The corners of the bull-eye
269	   * @throws NotFoundException If no valid bull-eye can be found
270	   */
271	  private ResultPoint[] getBullsEyeCorners(Point pCenter) throws NotFoundException {
272	
273	    Point pina = pCenter;
274	    Point pinb = pCenter;
275	    Point pinc = pCenter;
276	    Point pind = pCenter;
277	
278	    boolean color = true;
279	
280	    for (nbCenterLayers = 1; nbCenterLayers < 9; nbCenterLayers++) {
281	      Point pouta = getFirstDifferent(pina, color, 1, -1);
282	      Point poutb = getFirstDifferent(pinb, color, 1, 1);
283	      Point poutc = getFirstDifferent(pinc, color, -1, 1);
284	      Point poutd = getFirstDifferent(pind, color, -1, -1);
285	
286	      //d      a
287	      //
288	      //c      b
289	
290	      if (nbCenterLayers > 2) {
291	        float q = distance(poutd, pouta) * nbCenterLayers / (distance(pind, pina) * (nbCenterLayers + 2));
292	        if (q < 0.75 || q > 1.25 || !isWhiteOrBlackRectangle(pouta, poutb, poutc, poutd)) {
293	          break;
294	        }
295	      }
296	
297	      pina = pouta;
298	      pinb = poutb;
299	      pinc = poutc;
300	      pind = poutd;
301	
302	      color = !color;
303	    }
304	
305	    if (nbCenterLayers != 5 && nbCenterLayers != 7) {
306	      throw NotFoundException.getNotFoundInstance();
307	    }
308	
309	    compact = nbCenterLayers == 5;
310	
311	    // Expand the square by .5 pixel in each direction so that we're on the border
312	    // between the white square and the black square
313	    ResultPoint pinax = new ResultPoint(pina.getX() + 0.5f, pina.getY() - 0.5f);
314	    ResultPoint pinbx = new ResultPoint(pinb.getX() + 0.5f, pinb.getY() + 0.5f);
315	    ResultPoint pincx = new ResultPoint(pinc.getX() - 0.5f, pinc.getY() + 0.5f);
316	    ResultPoint pindx = new ResultPoint(pind.getX() - 0.5f, pind.getY() - 0.5f);
317	
318	    // Expand the square so that its corners are the centers of the points
319	    // just outside the bull's eye.
320	    return expandSquare(new ResultPoint[]{pinax, pinbx, pincx, pindx},
321	                        2 * nbCenterLayers - 3,
322	                        2 * nbCenterLayers);
323	  }
