325	  /**
326	   * Finds a candidate center point of an Aztec code from an image
327	   *
328	   * @return the center point
329	   */
330	  private Point getMatrixCenter() {
331	
332	    ResultPoint pointA;
333	    ResultPoint pointB;
334	    ResultPoint pointC;
335	    ResultPoint pointD;
336	
337	    //Get a white rectangle that can be the border of the matrix in center bull's eye or
338	    try {
339	
340	      ResultPoint[] cornerPoints = new WhiteRectangleDetector(image).detect();
341	      pointA = cornerPoints[0];
342	      pointB = cornerPoints[1];
343	      pointC = cornerPoints[2];
344	      pointD = cornerPoints[3];
345	
346	    } catch (NotFoundException e) {
347	
348	      // This exception can be in case the initial rectangle is white
349	      // In that case, surely in the bull's eye, we try to expand the rectangle.
350	      int cx = image.getWidth() / 2;
351	      int cy = image.getHeight() / 2;
352	      pointA = getFirstDifferent(new Point(cx + 7, cy - 7), false, 1, -1).toResultPoint();
353	      pointB = getFirstDifferent(new Point(cx + 7, cy + 7), false, 1, 1).toResultPoint();
354	      pointC = getFirstDifferent(new Point(cx - 7, cy + 7), false, -1, 1).toResultPoint();
355	      pointD = getFirstDifferent(new Point(cx - 7, cy - 7), false, -1, -1).toResultPoint();
356	
357	    }
358	
359	    //Compute the center of the rectangle
360	    int cx = MathUtils.round((pointA.getX() + pointD.getX() + pointB.getX() + pointC.getX()) / 4.0f);
361	    int cy = MathUtils.round((pointA.getY() + pointD.getY() + pointB.getY() + pointC.getY()) / 4.0f);
362	
363	    // Redetermine the white rectangle starting from previously computed center.
364	    // This will ensure that we end up with a white rectangle in center bull's eye
365	    // in order to compute a more accurate center.
366	    try {
367	      ResultPoint[] cornerPoints = new WhiteRectangleDetector(image, 15, cx, cy).detect();
368	      pointA = cornerPoints[0];
369	      pointB = cornerPoints[1];
370	      pointC = cornerPoints[2];
371	      pointD = cornerPoints[3];
372	    } catch (NotFoundException e) {
373	      // This exception can be in case the initial rectangle is white
374	      // In that case we try to expand the rectangle.
375	      pointA = getFirstDifferent(new Point(cx + 7, cy - 7), false, 1, -1).toResultPoint();
376	      pointB = getFirstDifferent(new Point(cx + 7, cy + 7), false, 1, 1).toResultPoint();
377	      pointC = getFirstDifferent(new Point(cx - 7, cy + 7), false, -1, 1).toResultPoint();
378	      pointD = getFirstDifferent(new Point(cx - 7, cy - 7), false, -1, -1).toResultPoint();
379	    }
380	
381	    // Recompute the center of the rectangle
382	    cx = MathUtils.round((pointA.getX() + pointD.getX() + pointB.getX() + pointC.getX()) / 4.0f);
383	    cy = MathUtils.round((pointA.getY() + pointD.getY() + pointB.getY() + pointC.getY()) / 4.0f);
384	
385	    return new Point(cx, cy);
386	  }
