398	  /**
399	   * Creates a BitMatrix by sampling the provided image.
400	   * topLeft, topRight, bottomRight, and bottomLeft are the centers of the squares on the
401	   * diagonal just outside the bull's eye.
402	   */
403	  private BitMatrix sampleGrid(BitMatrix image,
404	                               ResultPoint topLeft,
405	                               ResultPoint topRight,
406	                               ResultPoint bottomRight,
407	                               ResultPoint bottomLeft) throws NotFoundException {
408	
409	    GridSampler sampler = GridSampler.getInstance();
410	    int dimension = getDimension();
411	
412	    float low = dimension / 2.0f - nbCenterLayers;
413	    float high = dimension / 2.0f + nbCenterLayers;
414	
415	    return sampler.sampleGrid(image,
416	                              dimension,
417	                              dimension,
418	                              low, low,   // topleft
419	                              high, low,  // topright
420	                              high, high, // bottomright
421	                              low, high,  // bottomleft
422	                              topLeft.getX(), topLeft.getY(),
423	                              topRight.getX(), topRight.getY(),
424	                              bottomRight.getX(), bottomRight.getY(),
425	                              bottomLeft.getX(), bottomLeft.getY());
426	  }
