453	  /**
454	   * @return true if the border of the rectangle passed in parameter is compound of white points only
455	   *         or black points only
456	   */
457	  private boolean isWhiteOrBlackRectangle(Point p1,
458	                                          Point p2,
459	                                          Point p3,
460	                                          Point p4) {
461	
462	    int corr = 3;
463	
464	    p1 = new Point(Math.max(0, p1.getX() - corr), Math.min(image.getHeight() - 1, p1.getY() + corr));
465	    p2 = new Point(Math.max(0, p2.getX() - corr), Math.max(0, p2.getY() - corr));
466	    p3 = new Point(Math.min(image.getWidth() - 1, p3.getX() + corr),
467	                   Math.max(0, Math.min(image.getHeight() - 1, p3.getY() - corr)));
468	    p4 = new Point(Math.min(image.getWidth() - 1, p4.getX() + corr),
469	                   Math.min(image.getHeight() - 1, p4.getY() + corr));
470	
471	    int cInit = getColor(p4, p1);
472	
473	    if (cInit == 0) {
474	      return false;
475	    }
476	
477	    int c = getColor(p1, p2);
478	
479	    if (c != cInit) {
480	      return false;
481	    }
482	
483	    c = getColor(p2, p3);
484	
485	    if (c != cInit) {
486	      return false;
487	    }
488	
489	    c = getColor(p3, p4);
490	
491	    return c == cInit;
492	
493	  }
494	
495	  /**
496	   * Gets the color of a segment
497	   *
498	   * @return 1 if segment more than 90% black, -1 if segment is more than 90% white, 0 else
499	   */
500	  private int getColor(Point p1, Point p2) {
501	    float d = distance(p1, p2);
502	    if (d == 0.0f) {
503	      return 0;
504	    }
505	    float dx = (p2.getX() - p1.getX()) / d;
506	    float dy = (p2.getY() - p1.getY()) / d;
507	    int error = 0;
508	
509	    float px = p1.getX();
510	    float py = p1.getY();
511	
512	    boolean colorModel = image.get(p1.getX(), p1.getY());
513	
514	    int iMax = (int) Math.floor(d);
515	    for (int i = 0; i < iMax; i++) {
516	      if (image.get(MathUtils.round(px), MathUtils.round(py)) != colorModel) {
517	        error++;
518	      }
519	      px += dx;
520	      py += dy;
521	    }
522	
523	    float errRatio = error / d;
524	
525	    if (errRatio > 0.1f && errRatio < 0.9f) {
526	      return 0;
527	    }
528	
529	    return (errRatio <= 0.1f) == colorModel ? 1 : -1;
530	  }
531	
532	  /**
533	   * Gets the coordinate of the first point with a different color in the given direction
534	   */
535	  private Point getFirstDifferent(Point init, boolean color, int dx, int dy) {
536	    int x = init.getX() + dx;
537	    int y = init.getY() + dy;
538	
539	    while (isValid(x, y) && image.get(x, y) == color) {
540	      x += dx;
541	      y += dy;
542	    }
543	
544	    x -= dx;
545	    y -= dy;
546	
547	    while (isValid(x, y) && image.get(x, y) == color) {
548	      x += dx;
549	    }
550	    x -= dx;
551	
552	    while (isValid(x, y) && image.get(x, y) == color) {
553	      y += dy;
554	    }
555	    y -= dy;
556	
557	    return new Point(x, y);
558	  }
559	
560	  /**
561	   * Expand the square represented by the corner points by pushing out equally in all directions
562	   *
563	   * @param cornerPoints the corners of the square, which has the bull's eye at its center
564	   * @param oldSide the original length of the side of the square in the target bit matrix
565	   * @param newSide the new length of the size of the square in the target bit matrix
566	   * @return the corners of the expanded square
567	   */
568	  private static ResultPoint[] expandSquare(ResultPoint[] cornerPoints, int oldSide, int newSide) {
569	    float ratio = newSide / (2.0f * oldSide);
570	    float dx = cornerPoints[0].getX() - cornerPoints[2].getX();
571	    float dy = cornerPoints[0].getY() - cornerPoints[2].getY();
572	    float centerx = (cornerPoints[0].getX() + cornerPoints[2].getX()) / 2.0f;
573	    float centery = (cornerPoints[0].getY() + cornerPoints[2].getY()) / 2.0f;
574	
575	    ResultPoint result0 = new ResultPoint(centerx + ratio * dx, centery + ratio * dy);
576	    ResultPoint result2 = new ResultPoint(centerx - ratio * dx, centery - ratio * dy);
577	
578	    dx = cornerPoints[1].getX() - cornerPoints[3].getX();
579	    dy = cornerPoints[1].getY() - cornerPoints[3].getY();
580	    centerx = (cornerPoints[1].getX() + cornerPoints[3].getX()) / 2.0f;
581	    centery = (cornerPoints[1].getY() + cornerPoints[3].getY()) / 2.0f;
582	    ResultPoint result1 = new ResultPoint(centerx + ratio * dx, centery + ratio * dy);
583	    ResultPoint result3 = new ResultPoint(centerx - ratio * dx, centery - ratio * dy);
584	
585	    return new ResultPoint[]{result0, result1, result2, result3};
586	  }
