21	/**
22	 * @author Guenther Grau
23	 */
24	class DetectionResultColumn {
25	
26	  private static final int MAX_NEARBY_DISTANCE = 5;
27	
28	  private final BoundingBox boundingBox;
29	  private final Codeword[] codewords;
30	
31	  DetectionResultColumn(BoundingBox boundingBox) {
32	    this.boundingBox = new BoundingBox(boundingBox);
33	    codewords = new Codeword[boundingBox.getMaxY() - boundingBox.getMinY() + 1];
34	  }
35	
36	  final Codeword getCodewordNearby(int imageRow) {
37	    Codeword codeword = getCodeword(imageRow);
38	    if (codeword != null) {
39	      return codeword;
40	    }
41	    for (int i = 1; i < MAX_NEARBY_DISTANCE; i++) {
42	      int nearImageRow = imageRowToCodewordIndex(imageRow) - i;
43	      if (nearImageRow >= 0) {
44	        codeword = codewords[nearImageRow];
45	        if (codeword != null) {
46	          return codeword;
47	        }
48	      }
49	      nearImageRow = imageRowToCodewordIndex(imageRow) + i;
50	      if (nearImageRow < codewords.length) {
51	        codeword = codewords[nearImageRow];
52	        if (codeword != null) {
53	          return codeword;
54	        }
55	      }
56	    }
57	    return null;
58	  }
59	
60	  final int imageRowToCodewordIndex(int imageRow) {
61	    return imageRow - boundingBox.getMinY();
62	  }
63	
64	  final void setCodeword(int imageRow, Codeword codeword) {
65	    codewords[imageRowToCodewordIndex(imageRow)] = codeword;
66	  }
67	
68	  final Codeword getCodeword(int imageRow) {
69	    return codewords[imageRowToCodewordIndex(imageRow)];
70	  }
71	
72	  final BoundingBox getBoundingBox() {
73	    return boundingBox;
74	  }
75	
76	  final Codeword[] getCodewords() {
77	    return codewords;
78	  }
79	
80	  @Override
81	  public String toString() {
82	    try (Formatter formatter = new Formatter()) {
83	      int row = 0;
84	      for (Codeword codeword : codewords) {
85	        if (codeword == null) {
86	          formatter.format("%3d:    |   %n", row++);
87	          continue;
88	        }
89	        formatter.format("%3d: %3d|%3d%n", row++, codeword.getRowNumber(), codeword.getValue());
90	      }
91	      return formatter.toString();
92	    }
93	  }
