public int getNextUnset(int from) {
  return getNext(from, false);
}

/**
 * Shared implementation of {@link #getNextSet(int)} and {@link #getNextUnset(int)}: the two scans
 * are identical except that the search for an unset bit inverts each word as it is read.
 *
 * @param from first bit to check
 * @param set if {@code true}, finds the next set bit; if {@code false}, the next unset bit
 * @return index of the next matching bit at or after {@code from}, or {@code size} if none
 */
private int getNext(int from, boolean set) {
  if (from >= size) {
    return size;
  }
  int bitsOffset = from / 32;
  int currentBits = set ? bits[bitsOffset] : ~bits[bitsOffset];
  // mask off lesser bits first
  currentBits &= -(1 << (from & 0x1F));
  while (currentBits == 0) {
    if (++bitsOffset == bits.length) {
      return size;
    }
    currentBits = set ? bits[bitsOffset] : ~bits[bitsOffset];
  }
  int result = (bitsOffset * 32) + Integer.numberOfTrailingZeros(currentBits);
  return Math.min(result, size);
