import java.io.File;
import java.lang.reflect.Method;
import java.net.URL;
import java.net.URLClassLoader;
import java.util.Random;

/** Differential + oracle test for BitArray.getNextSet / getNextUnset: original vs refactored. */
public final class BaDiff {

  static URLClassLoader loader(String dir) throws Exception {
    return new URLClassLoader(new URL[]{ new File(dir).toURI().toURL() }, null);
  }

  static final class Api {
    final Class<?> cls;
    final Method ctor; // via constructor(int)
    final Method set;
    final Method get;
    final Method getNextSet;
    final Method getNextUnset;
    final java.lang.reflect.Constructor<?> construct;
    Api(ClassLoader cl) throws Exception {
      cls = Class.forName("com.google.zxing.common.BitArray", true, cl);
      construct = cls.getConstructor(int.class);
      set = cls.getMethod("set", int.class);
      get = cls.getMethod("get", int.class);
      getNextSet = cls.getMethod("getNextSet", int.class);
      getNextUnset = cls.getMethod("getNextUnset", int.class);
      ctor = null;
    }
    Object make(boolean[] bits) throws Exception {
      Object o = construct.newInstance(bits.length);
      for (int i = 0; i < bits.length; i++) {
        if (bits[i]) {
          set.invoke(o, i);
        }
      }
      return o;
    }
  }

  // Naive oracle on a boolean[] with logical size = bits.length.
  static int oracleNext(boolean[] bits, int from, boolean wantSet) {
    int size = bits.length;
    if (from >= size) {
      return size;
    }
    for (int i = from; i < size; i++) {
      if (bits[i] == wantSet) {
        return i;
      }
    }
    return size;
  }

  public static void main(String[] args) throws Exception {
    Api oldA = new Api(loader(args[0]));
    Api newA = new Api(loader(args[1]));
    Random r = new Random(99);

    long comparisons = 0;
    long mism = 0;
    long oracleChecks = 0;
    long oracleMism = 0;

    // sizes: include boundaries around 32-bit words and empty/small arrays
    int[] fixedSizes = { 0, 1, 2, 31, 32, 33, 63, 64, 65, 96, 100, 127, 128, 129 };
    for (int trial = 0; trial < 60000; trial++) {
      int size;
      if (trial < fixedSizes.length * 50) {
        size = fixedSizes[trial % fixedSizes.length];
      } else {
        size = r.nextInt(300);
      }
      boolean[] pattern = new boolean[size];
      int mode = r.nextInt(5);
      for (int i = 0; i < size; i++) {
        switch (mode) {
          case 0: pattern[i] = r.nextBoolean(); break;        // random
          case 1: pattern[i] = false; break;                   // all zero
          case 2: pattern[i] = true; break;                    // all one
          case 3: pattern[i] = (i % 2 == 0); break;            // alternating
          default: pattern[i] = r.nextInt(10) == 0; break;     // sparse
        }
      }
      Object oldO = oldA.make(pattern);
      Object newO = newA.make(pattern);

      // test every from in [0, size] plus a few beyond
      for (int from = 0; from <= size + 2; from++) {
        int os = (int) oldA.getNextSet.invoke(oldO, from);
        int ns = (int) newA.getNextSet.invoke(newO, from);
        int ou = (int) oldA.getNextUnset.invoke(oldO, from);
        int nu = (int) newA.getNextUnset.invoke(newO, from);
        comparisons += 2;
        if (os != ns || ou != nu) {
          mism++;
          if (mism <= 20) {
            System.out.println("MISMATCH size=" + size + " from=" + from +
                " set(old=" + os + ",new=" + ns + ") unset(old=" + ou + ",new=" + nu + ")");
          }
        }
        // oracle check (only for from within [0,size], where naive scan is well-defined)
        if (from <= size) {
          int expS = oracleNext(pattern, from, true);
          int expU = oracleNext(pattern, from, false);
          oracleChecks += 2;
          if (ns != expS || nu != expU) {
            oracleMism++;
            if (oracleMism <= 20) {
              System.out.println("ORACLE MISMATCH size=" + size + " from=" + from +
                  " set(new=" + ns + ",oracle=" + expS + ") unset(new=" + nu + ",oracle=" + expU + ")");
            }
          }
        }
      }
    }
    System.out.println("----");
    System.out.println("old-vs-new comparisons: " + comparisons + ", mismatches: " + mism);
    System.out.println("new-vs-oracle checks:   " + oracleChecks + ", mismatches: " + oracleMism);
    System.out.println((mism == 0 && oracleMism == 0) ? "RESULT: IDENTICAL & ORACLE-CORRECT" : "RESULT: DIFFERENCES FOUND");
  }
}

